// Desplazamientos calibrados a mano (ver conversación) para que las piezas
// del cuerpo encastren bien debajo de la cabeza — el paquete no trae estas
// posiciones documentadas en píxeles, así que se ajustaron por prueba visual.
const OFF = {
  cabeza: [0, 0],
  brazoIzq: [33, 118], brazoDer: [100, 118],
  cuerpo: [55, 112],
  piernaIzq: [59, 137], piernaDer: [73, 137],
  camisa: [52, 112],
  mangaIzq: [33, 118], mangaDer: [100, 118],
};

function grupo(inner, x, y) {
  return inner ? `<g transform="translate(${x},${y})">${inner}</g>` : "";
}

