// Combos de pelo: qué pieza "front"/"back" del paquete arma cada estilo.
const PELO_COMBOS = {
  corto: { front: "regular", back: "short" },
  elegante: { front: "elegant", back: "long" },
  rizado: { front: "curly", back: "curly" },
  chupchik: { front: "chupchik", back: null },
  calvo: { front: null, back: null },
};

// Combos de atuendo: camisa + mangas + pantalón.
const ATUENDO_COMBOS = {
  tunica: { camisa: "dress", manga: "long", pantalon: "pants" },
  casual: { camisa: "trousers", manga: "short", pantalon: "shorts" },
  elegante: { camisa: "dress", manga: "short", pantalon: "pants" },
};

export function svgCuerpoYCara(cuerpoKey) {
  const m = (cuerpoKey || "tint_1_smile").match(/^(tint_\d+)_(.+)$/);
  const tint = m ? m[1] : "tint_1";
  const expresion = m ? m[2] : "smile";
  const partes = PIEL_TINTS[tint] || PIEL_TINTS.tint_1;
  const cara = CARAS[expresion] || CARAS.smile;
  return grupo(partes.arm, ...OFF.brazoIzq) + grupo(partes.arm, ...OFF.brazoDer) +
    grupo(partes.body, ...OFF.cuerpo) +
    grupo(partes.leg, ...OFF.piernaIzq) + grupo(partes.leg, ...OFF.piernaDer) +
    grupo(partes.head, ...OFF.cabeza) + grupo(partes.cheeks, ...OFF.cabeza) +
    grupo(cara, ...OFF.cabeza);
}

export function svgPeloAtras(peloKey, color) {
  const combo = PELO_COMBOS[peloKey] || PELO_COMBOS.corto;
  const c = color || "brown";
  return combo.back ? grupo(PELO_ATRAS[combo.back]?.[c], ...OFF.cabeza) : "";
}

export function svgPeloFrente(peloKey, color) {
  const combo = PELO_COMBOS[peloKey] || PELO_COMBOS.corto;
  const c = color || "brown";
  return combo.front ? grupo(PELO_FRENTE[combo.front]?.[c], ...OFF.cabeza) : "";
}

export function svgAtuendoPersonaje(atuendoKey, color) {
  const combo = ATUENDO_COMBOS[atuendoKey] || ATUENDO_COMBOS.tunica;
  const c = color || "blue";
  return grupo(MANGAS[combo.manga]?.[c], ...OFF.mangaIzq) +
    grupo(MANGAS[combo.manga]?.[c], ...OFF.mangaDer) +
    grupo(CAMISAS[combo.camisa]?.[c], ...OFF.camisa) +
    grupo(PANTALONES[combo.pantalon], ...OFF.piernaIzq) +
    grupo(PANTALONES[combo.pantalon], ...OFF.piernaDer);
}

// Accesorios de fantasía dibujados a mano (el paquete no trae corona/capa/etc.)
// + gafas reales del paquete.
const CONTORNO = "#2D2250";
export function svgAccesorioPersonaje(key) {
  switch (key) {
    case "gafas_redondas":
      return grupo(GAFAS.round_black, ...OFF.cabeza);
    case "gafas_cuadradas":
      return grupo(GAFAS.square_black, ...OFF.cabeza);
    case "corona":
      return `<path d="M36 20 L41 6 L49 15 L54 3 L59 15 L67 6 L72 20 Z" fill="#FBBF24" stroke="#92400E" stroke-width="1.2" stroke-linejoin="round" />
        <circle cx="54" cy="14" r="2.3" fill="#EF4444" stroke="#92400E" stroke-width="0.6" />
        <circle cx="43" cy="17" r="1.6" fill="#3B82F6" stroke="#92400E" stroke-width="0.5" />
        <circle cx="65" cy="17" r="1.6" fill="#3B82F6" stroke="#92400E" stroke-width="0.5" />
        <path d="M36 20 L72 20" stroke="#92400E" stroke-width="1" />`;
    case "sombrero_mago":
      return `<path d="M54 0 L70 34 L38 34 Z" fill="#5B21B6" stroke="${CONTORNO}" stroke-width="1.3" stroke-linejoin="round" />
        <ellipse cx="54" cy="34" rx="22" ry="4.5" fill="#5B21B6" stroke="${CONTORNO}" stroke-width="1.3" />
        <path d="M47 24 L49 18 L52 24 L58 24 L53.5 27.5 L55 33.5 L49.5 30 L44 33.5 L46 27 Z" fill="#FBBF24" />`;
    case "capa":
      return `<path d="M26 100 Q14 128 26 155 Q34 157 36 151 L31 133 Q27 118 33 100 Z" fill="#DC2626" stroke="${CONTORNO}" stroke-width="1.3" />
        <path d="M82 100 Q94 128 82 155 Q74 157 72 151 L77 133 Q81 118 75 100 Z" fill="#DC2626" stroke="${CONTORNO}" stroke-width="1.3" />
        <circle cx="54" cy="100" r="2.6" fill="#FBBF24" stroke="${CONTORNO}" stroke-width="0.8" />`;
    case "antifaz":
      return `<path d="M34 62 Q44 56 53 62 Q44 70 34 67 Z" fill="${CONTORNO}" />
        <path d="M74 62 Q64 56 55 62 Q64 70 74 67 Z" fill="${CONTORNO}" />
        <path d="M53 62 L55 62" stroke="${CONTORNO}" stroke-width="2.4" />`;
    case "ninguno":
    default:
      return "";
  }
}

// Arma el SVG completo del personaje — orden de capas: pelo de atrás
// (detrás de la cabeza), cuerpo/piel/cara, atuendo (encima de la piel,
// para "vestirla"), pelo de adelante (flequillo, encima de la frente),
// y por último el accesorio (arriba de todo).
export function personajeSvg({ cuerpoKey, peloKey, peloColor, atuendoKey, atuendoColor, accesorioKey }) {
  return `
    ${svgPeloAtras(peloKey || "corto", peloColor || "brown")}
    ${svgCuerpoYCara(cuerpoKey || "tint_1_smile")}
    ${svgAtuendoPersonaje(atuendoKey || "tunica", atuendoColor || "blue")}
    ${svgPeloFrente(peloKey || "corto", peloColor || "brown")}
    ${svgAccesorioPersonaje(accesorioKey || "ninguno")}
  `;
}

export const COLORES_PELO_DISPONIBLES = ["black", "blond", "blue", "brown", "green", "orange", "red", "violet", "white"];
export const COLORES_ATUENDO_DISPONIBLES = ["black", "blue", "green", "orange", "red", "violet", "white"];
